fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Get the last character as a Unicode scalar value
    let last_char = match txt.chars().last() {
        Some(c) => c,
        None => return false, // empty string
    };

    // Check that last char is an ASCII alphabetic letter
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // If string has only one character, return true
    if txt.chars().count() == 1 {
        return true;
    }

    // If more than one char, get the penultimate character
    // We can collect chars into a Vec<char> safely for this
    let chars: Vec<char> = txt.chars().collect();
    let penultimate_char = chars[chars.len() - 2];

    // Return true if penultimate char is a space, else false
    penultimate_char == ' '
}